INSERT INTO public.basic_actions (id, name, category, cost, check_type, effect, description) VALUES ('action_1', 'Pukulan Fisik (Unarmed Strike)', 'basic_combat', NULL, 'Physique / Power', NULL, 'Tinju mentah atau tamparan spontan saat adu fisik jarak dekat.') ON CONFLICT (id) DO UPDATE SET name = EXCLUDED.name, category = EXCLUDED.category, cost = EXCLUDED.cost, check_type = EXCLUDED.check_type, effect = EXCLUDED.effect, description = EXCLUDED.description;
INSERT INTO public.basic_actions (id, name, category, cost, check_type, effect, description) VALUES ('action_2', 'Tendangan Cepat (Snap Kick)', 'basic_combat', NULL, 'Physique / Agility', NULL, 'Tendangan mendadak mengarah ke betis atau paha lawan.') ON CONFLICT (id) DO UPDATE SET name = EXCLUDED.name, category = EXCLUDED.category, cost = EXCLUDED.cost, check_type = EXCLUDED.check_type, effect = EXCLUDED.effect, description = EXCLUDED.description;
INSERT INTO public.basic_actions (id, name, category, cost, check_type, effect, description) VALUES ('action_3', 'Dorongan Kuat (Shove)', 'basic_combat', NULL, 'Physique / Power vs Target Physique Save', NULL, 'Mendorong lawan dengan kedua tangan penuh tenaga agar kehilangan keseimbangan.') ON CONFLICT (id) DO UPDATE SET name = EXCLUDED.name, category = EXCLUDED.category, cost = EXCLUDED.cost, check_type = EXCLUDED.check_type, effect = EXCLUDED.effect, description = EXCLUDED.description;
INSERT INTO public.basic_actions (id, name, category, cost, check_type, effect, description) VALUES ('action_4', 'Tangkis & Bertahan (Dodge & Guard)', 'basic_combat', NULL, 'Otomatis', NULL, 'Memasang kuda-kuda rapat dan fokus memperhatikan gerak-gerik lawan.') ON CONFLICT (id) DO UPDATE SET name = EXCLUDED.name, category = EXCLUDED.category, cost = EXCLUDED.cost, check_type = EXCLUDED.check_type, effect = EXCLUDED.effect, description = EXCLUDED.description;
INSERT INTO public.basic_actions (id, name, category, cost, check_type, effect, description) VALUES ('action_5', 'Kabur & Menghindar (Disengage)', 'basic_combat', NULL, 'Physique / Agility', NULL, 'Mundur dengan langkah cerdas memanfaatkan celah gerak lawan.') ON CONFLICT (id) DO UPDATE SET name = EXCLUDED.name, category = EXCLUDED.category, cost = EXCLUDED.cost, check_type = EXCLUDED.check_type, effect = EXCLUDED.effect, description = EXCLUDED.description;
INSERT INTO public.basic_actions (id, name, category, cost, check_type, effect, description) VALUES ('action_6', 'Tatapan Intimidasi (Intimidating Stare)', 'basic_social', NULL, 'Looks / Aura vs Target Mind Save', 'Target ragu bertindak (Disadvantage aksi berikutnya).', 'Menatap dengan ekspresi dingin dan intensitas yang membuat target tidak nyaman.') ON CONFLICT (id) DO UPDATE SET name = EXCLUDED.name, category = EXCLUDED.category, cost = EXCLUDED.cost, check_type = EXCLUDED.check_type, effect = EXCLUDED.effect, description = EXCLUDED.description;
INSERT INTO public.basic_actions (id, name, category, cost, check_type, effect, description) VALUES ('action_7', 'Senyuman Persuasi (Charming Smile)', 'basic_social', NULL, 'Looks / Charm vs Target Mind Save', 'Target tertegun sejenak; Disadvantage pada save berikutnya.', 'Memberikan senyuman tulus yang membuat degup jantung target berdebar kencang.') ON CONFLICT (id) DO UPDATE SET name = EXCLUDED.name, category = EXCLUDED.category, cost = EXCLUDED.cost, check_type = EXCLUDED.check_type, effect = EXCLUDED.effect, description = EXCLUDED.description;
INSERT INTO public.basic_actions (id, name, category, cost, check_type, effect, description) VALUES ('action_8', 'Sindiran / Provokasi (Taunt)', 'basic_social', NULL, 'Intelligent / People vs Target Mind Save', 'Target terprovokasi: wajib fokus menyerangmu pada gilirannya.', 'Melontarkan kata-kata tajam yang tepat sasaran untuk memancing reaksi emosional target.') ON CONFLICT (id) DO UPDATE SET name = EXCLUDED.name, category = EXCLUDED.category, cost = EXCLUDED.cost, check_type = EXCLUDED.check_type, effect = EXCLUDED.effect, description = EXCLUDED.description;
INSERT INTO public.basic_actions (id, name, category, cost, check_type, effect, description) VALUES ('action_9', 'Rayuan Halus (Subtle Flirt)', 'basic_social', NULL, 'Looks / Charm vs Target Mind Save', 'Jika berhasil, target memberikan Advantage pada percakapan sosial berikutnya denganmu.', 'Mengirimkan sinyal halus lewat tatapan atau gestur kecil yang membuka pintu percakapan.') ON CONFLICT (id) DO UPDATE SET name = EXCLUDED.name, category = EXCLUDED.category, cost = EXCLUDED.cost, check_type = EXCLUDED.check_type, effect = EXCLUDED.effect, description = EXCLUDED.description;
INSERT INTO public.basic_actions (id, name, category, cost, check_type, effect, description) VALUES ('action_10', 'Bantuan & Dukungan (Help / Support)', 'basic_social', NULL, 'Mind / Interpersonal', 'Memberikan Advantage kepada 1 sekutu pada roll check atau serangan berikutnya.', 'Membantu, mendukung, atau memberikan ide kepada teman yang sedang berusaha melakukan sesuatu.') ON CONFLICT (id) DO UPDATE SET name = EXCLUDED.name, category = EXCLUDED.category, cost = EXCLUDED.cost, check_type = EXCLUDED.check_type, effect = EXCLUDED.effect, description = EXCLUDED.description;
INSERT INTO public.calendar_events (id, term, name, event_type, description) VALUES ('cal_01', 'Semester 1 (Musim Semi)', 'Upacara Masuk & Pembagian Kelas Baru', NULL, 'Momen berkenalan dengan teman sebangku dan melihat siapa yang satu kelas denganmu.') ON CONFLICT (id) DO UPDATE SET term = EXCLUDED.term, name = EXCLUDED.name, event_type = EXCLUDED.event_type, description = EXCLUDED.description;
INSERT INTO public.calendar_events (id, term, name, event_type, description) VALUES ('cal_02', 'Semester 1', 'Ujian Tengah Semester (UTS / Midterms)', NULL, 'Pertaruhan nilai akademis, begadang kelompok belajar di perpustakaan.') ON CONFLICT (id) DO UPDATE SET term = EXCLUDED.term, name = EXCLUDED.name, event_type = EXCLUDED.event_type, description = EXCLUDED.description;
INSERT INTO public.calendar_events (id, term, name, event_type, description) VALUES ('cal_03', 'Semester 1', 'Festival Olahraga (Undoukai)', NULL, 'Lari estafet, tarik tambang, dan kesempatan menyemangati gebetan dari pinggir lapangan.') ON CONFLICT (id) DO UPDATE SET term = EXCLUDED.term, name = EXCLUDED.name, event_type = EXCLUDED.event_type, description = EXCLUDED.description;
INSERT INTO public.calendar_events (id, term, name, event_type, description) VALUES ('cal_04', 'Liburan Semester 1', 'Liburan Musim Panas & Festival Kembang Api', NULL, 'Mengenakan pakaian Yukata, janjian nonton kembang api kuil di malam hari.') ON CONFLICT (id) DO UPDATE SET term = EXCLUDED.term, name = EXCLUDED.name, event_type = EXCLUDED.event_type, description = EXCLUDED.description;
INSERT INTO public.calendar_events (id, term, name, event_type, description) VALUES ('cal_05', 'Semester 2 (Musim Gugur)', 'Festival Budaya Sekolah (Bunkasai)', NULL, 'Acara puncak tahunan! Rumah hantu, maid cafe kelas, dan konser band panggung sekolah.') ON CONFLICT (id) DO UPDATE SET term = EXCLUDED.term, name = EXCLUDED.name, event_type = EXCLUDED.event_type, description = EXCLUDED.description;
INSERT INTO public.calendar_events (id, term, name, event_type, description) VALUES ('cal_06', 'Semester 2', 'Study Tour Sekolah (Shuugakuryokou)', NULL, 'Perjalanan bus menginap ke Kyoto/daerah wisata; curhat rahasia malam hari di kamar hotel.') ON CONFLICT (id) DO UPDATE SET term = EXCLUDED.term, name = EXCLUDED.name, event_type = EXCLUDED.event_type, description = EXCLUDED.description;
INSERT INTO public.calendar_events (id, term, name, event_type, description) VALUES ('cal_07', 'Semester 2 (Musim Dingin)', 'Hari Valentine & White Day', NULL, 'Menaruh cokelat honmei (cinta tulus) atau giri (pertemanan) di dalam loker sepatu.') ON CONFLICT (id) DO UPDATE SET term = EXCLUDED.term, name = EXCLUDED.name, event_type = EXCLUDED.event_type, description = EXCLUDED.description;
INSERT INTO public.calendar_events (id, term, name, event_type, description) VALUES ('cal_08', 'Akhir Tahun Ajaran', 'Ujian Kenaikan Kelas & Upacara Kelulusan', NULL, 'Pengumuman kelulusan dan momen perpisahan yang penuh air mata kenangan.') ON CONFLICT (id) DO UPDATE SET term = EXCLUDED.term, name = EXCLUDED.name, event_type = EXCLUDED.event_type, description = EXCLUDED.description;
